import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { ITodoAppGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuest";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";

/**
 * Test guest join with new identity — verifies that a first-time visitor with an unseen
 * device fingerprint creates a fresh guest identity and receives valid JWT tokens.
 *
 * Validates the complete guest join flow including identity record creation, session
 * establishment, and JWT token issuance. Confirms that the fingerprint is correctly
 * stored and that brand-new records have identical created_at and updated_at timestamps.
 *
 * Also validates token structure: non-empty access and refresh tokens that differ from
 * each other, with expiration timestamps set in the future and the refresh window
 * extending beyond the access token's expiration.
 *
 * 1. First guest joins with a unique fingerprint, generating a new identity and session.
 * 2. Identity fields are validated: fingerprint matches input, created_at equals updated_at.
 * 3. Token fields are validated: non-empty, distinct access/refresh, future expirations.
 * 4. Second guest joins with a different fingerprint, confirming a distinct identity id.
 */
export async function test_api_guest_join_new_identity(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create first guest connection with a unique fingerprint
  const fingerprint1 = RandomGenerator.alphaNumeric(64);
  const href1 = typia.random<string & tags.Format<"uri">>();
  const referrer1 = typia.random<string & tags.Format<"uri">>();
  const guestConnection1: api.IConnection = { host: connection.host };
  const result1 = await authorize_guest_join(guestConnection1, {
    body: { fingerprint: fingerprint1, href: href1, referrer: referrer1 },
  });
  typia.assert(result1);
  // 2. Validate identity fields
  TestValidator.equals(
    "fingerprint matches input",
    result1.fingerprint,
    fingerprint1,
  );
  TestValidator.equals(
    "created_at equals updated_at",
    result1.created_at,
    result1.updated_at,
  );
  // 3. Validate token fields
  TestValidator.predicate(
    "access token non-empty",
    result1.token.access.length > 0,
  );
  TestValidator.predicate(
    "refresh token non-empty",
    result1.token.refresh.length > 0,
  );
  TestValidator.notEquals(
    "access and refresh tokens differ",
    result1.token.access,
    result1.token.refresh,
  );
  const now = new Date();
  const expiredAt = new Date(result1.token.expired_at);
  const refreshableUntil = new Date(result1.token.refreshable_until);
  TestValidator.predicate("access token not expired", expiredAt > now);
  TestValidator.predicate(
    "refresh window beyond access expiry",
    refreshableUntil > expiredAt,
  );
  // 4. Create second guest connection with different fingerprint
  const fingerprint2 = RandomGenerator.alphaNumeric(64);
  const href2 = typia.random<string & tags.Format<"uri">>();
  const referrer2 = typia.random<string & tags.Format<"uri">>();
  const guestConnection2: api.IConnection = { host: connection.host };
  const result2 = await authorize_guest_join(guestConnection2, {
    body: { fingerprint: fingerprint2, href: href2, referrer: referrer2 },
  });
  typia.assert(result2);
  // 5. Verify distinct identities
  TestValidator.notEquals("different guest identities", result1.id, result2.id);
  TestValidator.equals(
    "second fingerprint matches input",
    result2.fingerprint,
    fingerprint2,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { ITodoAppGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuest";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";

/**
 * Test returning guest identity persistence across sessions.
 *
 * Validates that a guest visitor with an already-known device fingerprint reuses the same guest identity record while receiving a brand new session with distinct JWT token pair.
 *
 * The test ensures that the guest identity (id, fingerprint, created_at) remains stable across multiple sessions, while session-scoped data (tokens, timestamps) is refreshed on each join operation. This confirms the upsert behavior where the fingerprint acts as the lookup key for identity reuse.
 *
 * 1. First join with fingerprint "fp-returning-001" — captures guest identity and token pair.
 * 2. Second join with the same fingerprint — verifies identity reuse and token rotation.
 * 3. Validates id, fingerprint, and created_at are identical across both joins.
 * 4. Validates updated_at is newer than created_at, confirming the record was touched.
 * 5. Validates access token, refresh token, expired_at, and refreshable_until differ between sessions.
 */
export async function test_api_guest_join_returning_identity(
  connection: api.IConnection,
): Promise<void> {
  const fingerprint = "fp-returning-001";
  // 1. First guest join
  const firstConnection: api.IConnection = { host: connection.host };
  const firstResult = await authorize_guest_join(firstConnection, {
    body: { fingerprint },
  });
  typia.assert(firstResult);
  // 2. Second guest join with same fingerprint
  const secondConnection: api.IConnection = { host: connection.host };
  const secondResult = await authorize_guest_join(secondConnection, {
    body: { fingerprint },
  });
  typia.assert(secondResult);
  // 3. Validate identity persistence
  TestValidator.equals("id unchanged", secondResult.id, firstResult.id);
  TestValidator.equals(
    "fingerprint matches",
    secondResult.fingerprint,
    fingerprint,
  );
  // 4. Validate timestamps
  TestValidator.equals(
    "created_at unchanged",
    secondResult.created_at,
    firstResult.created_at,
  );
  TestValidator.predicate(
    "updated_at more recent than created_at",
    () => secondResult.updated_at > firstResult.created_at,
  );
  // 5. Validate token rotation
  TestValidator.notEquals(
    "access token rotates",
    secondResult.token.access,
    firstResult.token.access,
  );
  TestValidator.notEquals(
    "refresh token rotates",
    secondResult.token.refresh,
    firstResult.token.refresh,
  );
  TestValidator.notEquals(
    "expired_at is new",
    secondResult.token.expired_at,
    firstResult.token.expired_at,
  );
  TestValidator.notEquals(
    "refreshable_until is new",
    secondResult.token.refreshable_until,
    firstResult.token.refreshable_until,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { ITodoAppGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuest";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";

/**
 * Test guest session refresh with valid refresh token from prior join.
 *
 * Validates that a guest can successfully extend their session by exchanging a valid refresh token for a new JWT token pair. The refresh token is obtained from a prior join operation, and the new session preserves the guest identity while issuing distinct tokens.
 *
 * 1. Join creates a guest identity with device fingerprint and returns initial tokens.
 * 2. Refresh exchanges the initial refresh token for a new token pair.
 * 3. Validates identity preservation: id, fingerprint, created_at, and updated_at unchanged.
 * 4. Validates token rotation: new access and refresh tokens differ from originals and are non-empty.
 * 5. Validates expiration chronology: expired_at and refreshable_until are future dates, with refreshable_until after expired_at.
 */
export async function test_api_guest_session_refresh_success(
  connection: api.IConnection,
): Promise<void> {
  // 1. Join: create guest identity and obtain initial tokens
  const guestConnection: api.IConnection = { host: connection.host };
  const joinResponse = await authorize_guest_join(guestConnection, {});
  typia.assert(joinResponse);
  // 2. Refresh: exchange the initial refresh token for a new token pair
  const refreshConnection: api.IConnection = { host: connection.host };
  const refreshResponse = await authorize_guest_refresh(refreshConnection, {
    body: {
      refreshToken: joinResponse.token.refresh,
    } satisfies ITodoAppGuest.IRefresh,
  });
  typia.assert(refreshResponse);
  // 3. Validate identity preservation
  TestValidator.equals(
    "guest id preserved",
    refreshResponse.id,
    joinResponse.id,
  );
  TestValidator.equals(
    "fingerprint preserved",
    refreshResponse.fingerprint,
    joinResponse.fingerprint,
  );
  TestValidator.equals(
    "created_at unchanged",
    refreshResponse.created_at,
    joinResponse.created_at,
  );
  TestValidator.equals(
    "updated_at reflects join time, not refreshed",
    refreshResponse.updated_at,
    joinResponse.updated_at,
  );
  // 4. Validate token rotation
  TestValidator.notEquals(
    "new access token distinct",
    refreshResponse.token.access,
    joinResponse.token.access,
  );
  TestValidator.notEquals(
    "new refresh token distinct",
    refreshResponse.token.refresh,
    joinResponse.token.refresh,
  );
  TestValidator.predicate(
    "new access token non-empty",
    refreshResponse.token.access.length > 0,
  );
  TestValidator.predicate(
    "new refresh token non-empty",
    refreshResponse.token.refresh.length > 0,
  );
  // 5. Validate expiration chronology
  const now = new Date();
  const expiredAt = new Date(refreshResponse.token.expired_at);
  const refreshableUntil = new Date(refreshResponse.token.refreshable_until);
  TestValidator.predicate(
    "expired_at is future",
