   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Delete(":resetId")
  public async erase(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("resetId")
    resetId: string & tags.Format<"uuid">,
  ): Promise<void> {
    try {
      return await deleteTodoAppMemberPasswordResetsResetId({
        member,
        resetId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
